function resolveUser(body) {
  const crypto = require('crypto');
  try {
    if (body.init_data) {
      // ручной разбор строки initData (без стандартного URL-парсера:
      // в песочнице Code node он недоступен);
      // data_check_string строится из СЫРЫХ значений, как требует Telegram
      const raw = String(body.init_data);
      let hash = '';
      const pairs = [];
      for (const part of raw.split('&')) {
        const eq = part.indexOf('=');
        if (eq < 0) continue;
        const k = part.slice(0, eq);
        const v = part.slice(eq + 1);
        if (k === 'hash') { hash = v; continue; }
        if (k === 'signature') continue;
        pairs.push([k, v]);
      }
      const dcs = pairs.map(([k, v]) => k + '=' + v).sort().join('&');
      const secret = crypto.createHmac('sha256', 'WebAppData').update('__BOT_TOKEN__').digest();
      const calc = crypto.createHmac('sha256', secret).update(dcs).digest('hex');
      if (!hash || calc !== hash) return null;
      const uv = (pairs.find(([k]) => k === 'user') || [])[1] || '{}';
      const u = JSON.parse(decodeURIComponent(uv));
      return u.username ? '@' + String(u.username) : (u.id ? String(u.id) : null);
    }
    if (body.user && body.sig) {
      const calc = crypto.createHmac('sha256', '__SIGN_SECRET__').update(String(body.user)).digest('hex');
      return calc === String(body.sig) ? String(body.user) : null;
    }
  } catch (e) {
    return null;
  }
  return null;
}
const body = $input.first().json.body || {};
const sel = String(body.sel || 'start');
const services = { consult: 'Консультация', integration: 'Интеграция', dev: 'Разработка' };
function kb(rows) {
  return rows.map((r) => r.map(([t, cb]) => ({ text: t, callback_data: cb })));
}
let out;
if (sel === 'start') {
  out = {
    stage: 'show',
    text: '🪄 Подбор услуги — 3 шага. Шаг 1/3: выберите услугу:',
    buttons: kb([
      [['🧭 Консультация', 'wz:srv:consult']],
      [['🔌 Интеграция', 'wz:srv:integration']],
      [['⚙️ Разработка', 'wz:srv:dev']],
    ]),
  };
} else if (sel.startsWith('srv:')) {
  const svc = sel.slice(4);
  if (!services[svc]) {
    out = { stage: 'show', text: 'Неизвестная услуга, начните заново:', buttons: kb([[['🔄 С начала', 'wz:start']]]) };
  } else {
    // слоты берём из demo-10 (/webhook/demo/slots) — единый источник, тот же, что /slots (S1/S2)
    out = { stage: 'slots', svc };
  }
} else if (sel.startsWith('time:')) {
  const parts = sel.split(':');
  const slotId = parts[1] || '';
  const svc = parts[2] || '';
  if (!services[svc] || !/^\d{4}-\d{2}-\d{2}-\d{4}$/.test(slotId)) {
    out = { stage: 'show', text: 'Сессия устарела. Начните заново:', buttons: kb([[['🔄 С начала', 'wz:start']]]) };
  } else {
    const day = slotId.slice(0, 10);
    const hh = slotId.slice(11, 13) + ':' + slotId.slice(13, 15);
    out = {
      stage: 'show',
      text: 'Шаг 3/3 — проверьте:\n• Услуга: ' + services[svc] + '\n• Время: ' + day + ' ' + hh + '\n\nЗаписываем?',
      buttons: kb([
        [['✅ Записаться', 'wz:confirm:' + slotId + ':' + svc], ['❌ Отмена', 'wz:cancel']],
      ]),
    };
  }
} else if (sel.startsWith('confirm:')) {
  const parts = sel.split(':');
  const slotId = parts[1] || '';
  const svc = parts[2] || '';
  const u = (resolveUser(body) || '').trim().slice(0, 64);
  if (!u) {
    out = { stage: 'show', text: '⚠️ Не удалось подтвердить личность. Откройте демо через бота.', buttons: kb([[['🔄 С начала', 'wz:start']]]) };
  } else {
    // подпись для demo-10 (B1): тот же HMAC-SHA256(DEMO_SIGN_SECRET, user)
    const sig = require('crypto').createHmac('sha256', '__SIGN_SECRET__').update(u).digest('hex');
    out = { stage: 'book', slot_id: slotId, user: u, svc, sig };
  }
} else if (sel === 'cancel') {
  out = { stage: 'show', text: 'Отменено. /wizard — начать заново.', buttons: [] };
} else {
  out = { stage: 'show', text: 'Не понял выбор. /wizard — начать заново.', buttons: [] };
}
return [{ json: out }];

// Финал: результат брони -> текст + кнопки
const r = $input.first().json;
const kb = (rows) => rows.map((row) => row.map(([t, cb]) => ({ text: t, callback_data: cb })));
let out;
if (r && r.ok) {
  out = { stage: 'show', text: '✅ Готово! Вы записаны: ' + (r.booking ? r.booking.start : '') + '. Ждём вас!', buttons: kb([[['🔄 Ещё раз', 'wz:start']]]) };
} else {
  out = { stage: 'show', text: '⚠️ Не получилось: ' + ((r && r.error) || 'слот занят') + '. Начните заново:', buttons: kb([[['🔄 С начала', 'wz:start']]]) };
}
return [{ json: out }];

// Шаг 2/3 wizard: свободные слоты пришли из demo-10 — единый источник (тот же, что /slots)
const kb = (rows) => rows.map((row) => row.map(([t, cb]) => ({ text: t, callback_data: cb })));
const services = { consult: 'Консультация', integration: 'Интеграция', dev: 'Разработка' };
const route = $('Маршрут wizard').first().json;
const svc = (route && route.svc) || route.svc || '';
const r = $input.first().json;
const free = (r && r.ok === true && Array.isArray(r.slots)) ? r.slots.filter((s) => s && s.id && s.start) : [];
let out;
if (!free.length) {
  out = {
    stage: 'show',
    text: (r && r.ok === true)
      ? 'Свободных слотов нет — всё разобрано. Попробуйте позже.'
      : 'Не удалось загрузить слоты, попробуйте позже.',
    buttons: kb([[['🔄 Сначала', 'wz:start']]]),
  };
} else {
  const rows = [];
  for (let i = 0; i < free.length; i += 2) {
    rows.push(free.slice(i, i + 2).map((s) => ['📅 ' + s.start, 'wz:time:' + s.id + ':' + svc]));
  }
  rows.push([['❌ Отмена', 'wz:cancel']]);
  out = { stage: 'show', text: 'Услуга: ' + (services[svc] || svc) + '. Шаг 2/3: выберите время:', buttons: kb(rows) };
}
return [{ json: out }];
